int countWords(const std::string& str) {
    std::string s = str;
    for (auto& ch : s) {
        if (ch == '_') ch = ' ';
    }
    // trim leading and trailing spaces
    size_t start = s.find_first_not_of(' ');
    size_t end = s.find_last_not_of(' ');
    if (start == std::string::npos || end == std::string::npos) {
        return 0;
    }
    s = s.substr(start, end - start + 1);
    // replace multiple spaces with single space
    std::string result;
    bool inSpace = false;
    for (char ch : s) {
        if (isspace(ch)) {
            if (!inSpace) {
                result += ' ';
                inSpace = true;
            }
        } else {
            result += ch;
            inSpace = false;
        }
    }
    // split by space
    int count = 0;
    size_t pos = 0;
    while ((pos = result.find(' ')) != std::string::npos) {
        if (!result.substr(0, pos).empty()) {
            count++;
        }
        result.erase(0, pos + 1);
    }
    if (!result.empty()) {
        count++;
    }
    return count;
}

int main() {
    int n;
    std::cin >> n;
    std::string s;
    std::cin >> s;

    std::vector<int> indices;
    indices.push_back(-1);
    for (size_t i = 0; i < s.length(); ++i) {
        if (s[i] == '(' || s[i] == ')') {
            indices.push_back(i);
        }
    }

    int i = 1;
    int totalCount = 0;
    int maxLen = 0;
    std::string outsideText;

    while (i < static_cast<int>(indices.size()) - 1) {
        int startIdx = indices[i];
        int endIdx = indices[i + 1];
        std::string insideStr = s.substr(startIdx + 1, endIdx - startIdx - 1);
        int countWordsIn = countWords(insideStr);
        totalCount += countWordsIn;
        int prevIdx = indices[i - 1];
        outsideText += "_" + s.substr(prevIdx + 1, startIdx - prevIdx - 1);
        i += 2;
    }
    outsideText += "_" + s.substr(indices.back() + 1);

    // process outsideText
    for (auto& ch : outsideText) {
        if (ch == '_') ch = ' ';
    }
    // trim leading and trailing spaces
    size_t start = outsideText.find_first_not_of(' ');
    size_t end = outsideText.find_last_not_of(' ');
    if (start != std::string::npos && end != std::string::npos) {
        outsideText = outsideText.substr(start, end - start + 1);
    } else {
        outsideText.clear();
    }
    // replace multiple spaces with single space
    std::string cleaned;
    bool inSpace = false;
    for (char ch : outsideText) {
        if (isspace(ch)) {
            if (!inSpace) {
                cleaned += ' ';
                inSpace = true;
            }
        } else {
            cleaned += ch;
            inSpace = false;
        }
    }
    // split into words
    std::vector<std::string> outsideWords;
    size_t pos = 0;
    while ((pos = cleaned.find(' ')) != std::string::npos) {
        std::string word = cleaned.substr(0, pos);
        if (!word.empty()) {
            outsideWords.push_back(word);
        }
        cleaned.erase(0, pos + 1);
    }
    if (!cleaned.empty()) {
        outsideWords.push_back(cleaned);
    }

    for (const auto& w : outsideWords) {
        if (w.length() > maxLen) {
            maxLen = w.length();
        }
    }

    std::cout << maxLen << " " << totalCount;
    return 0;
}
